-- Complete Chilean commune catalog for dashboard and registration selectors.
-- Source: Biblioteca del Congreso Nacional (SIIT) / INE DPA: 16 regions, 346 communes.
-- Idempotent: existing curated slugs keep their IDs and receive canonical labels/order.

ON CONFLICT ("slug") DO UPDATE SET
  "name" = EXCLUDED."name",
  "regionName" = EXCLUDED."regionName",
  "communeName" = EXCLUDED."communeName",
  "isActive" = true,
  "position" = EXCLUDED."position",
  "updatedAt" = CURRENT_TIMESTAMP;
